using System;
using System.Collections.Generic;
using System.Linq;
using System.Runtime.CompilerServices;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Documents;
using System.Windows.Media;

// Change type and its layout budget, never the editor's coordinate system or document.
static class UiTypography {
 sealed class FontState {public double Size;}
 sealed class LengthState {public double Length;}
 sealed class WindowState {public double Width,Height,MinWidth,MinHeight,MaxWidth,MaxHeight;public int Applied=-1;public bool Busy;}
 static readonly ConditionalWeakTable<DependencyObject,FontState> fonts=new ConditionalWeakTable<DependencyObject,FontState>();
 static readonly ConditionalWeakTable<DependencyObject,LengthState> lengths=new ConditionalWeakTable<DependencyObject,LengthState>();
 static readonly ConditionalWeakTable<Window,WindowState> windows=new ConditionalWeakTable<Window,WindowState>();
 static readonly DependencyProperty ExcludedProperty=DependencyProperty.RegisterAttached("Excluded",typeof(bool),typeof(UiTypography),new PropertyMetadata(false));
 static bool installed;
 public static double Factor{get{return AppSettings.InterfaceFont/13.0;}}
 public static void Exclude(DependencyObject element){element.SetValue(ExcludedProperty,true);}
 public static void Attach(Window window){WindowState existing;if(windows.TryGetValue(window,out existing))return;var state=new WindowState{Width=window.Width,Height=window.Height,MinWidth=window.MinWidth,MinHeight=window.MinHeight,MaxWidth=window.MaxWidth,MaxHeight=window.MaxHeight};windows.Add(window,state);if(!installed){installed=true;AppSettings.Changed+=()=>{var app=Application.Current;if(app!=null)foreach(Window w in app.Windows.Cast<Window>().ToArray())Apply(w,false);};}window.SourceInitialized+=(s,e)=>Apply(window,true);window.Loaded+=(s,e)=>Apply(window,true);window.SizeChanged+=(s,e)=>CompactChallenge(window);}
 static IEnumerable<DependencyObject> Walk(DependencyObject node,HashSet<DependencyObject> seen){if(node==null||!seen.Add(node)||node is CodeEditor||(bool)node.GetValue(ExcludedProperty))yield break;yield return node;var text=node as TextBlock;if(text!=null)foreach(var inline in text.Inlines)foreach(var child in Walk(inline,seen))yield return child;foreach(object item in LogicalTreeHelper.GetChildren(node)){var child=item as DependencyObject;if(child!=null)foreach(var entry in Walk(child,seen))yield return entry;}if(node is Visual)for(int i=0;i<VisualTreeHelper.GetChildrenCount(node);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(node,i),seen))yield return child;}
 public static void Apply(Window window,bool force){WindowState state;if(!windows.TryGetValue(window,out state)||state.Busy||!force&&state.Applied==AppSettings.InterfaceFont)return;state.Busy=true;try{double factor=Factor;var all=Walk(window,new HashSet<DependencyObject>()).ToList();var changes=new List<Action>();foreach(var node in all){DependencyProperty property=node is Control?Control.FontSizeProperty:node is TextBlock?TextBlock.FontSizeProperty:node is TextElement?TextElement.FontSizeProperty:null;if(property!=null){bool explicitSize=node.ReadLocalValue(property) is double||node is Window||node is Button||node is ComboBox||node is ListBox||node is DataGrid;FontState font;if(fonts.TryGetValue(node,out font)||explicitSize){if(font==null){font=new FontState{Size=(double)node.GetValue(property)};fonts.Add(node,font);}var target=node;var dp=property;double size=font.Size;changes.Add(()=>target.SetCurrentValue(dp,size*factor));}}
    var grid=node as Grid;if(grid!=null&&!(grid is ConstellationMap)){foreach(var row in grid.RowDefinitions){if(!row.Height.IsAbsolute||row.Height.Value<22)continue;LengthState value;if(!lengths.TryGetValue(row,out value)){value=new LengthState{Length=row.Height.Value};lengths.Add(row,value);}row.Height=new GridLength(value.Length*factor);}foreach(var column in grid.ColumnDefinitions){if(!column.Width.IsAbsolute||column.Width.Value<100)continue;LengthState value;if(!lengths.TryGetValue(column,out value)){value=new LengthState{Length=column.Width.Value};lengths.Add(column,value);}column.Width=new GridLength(value.Length*factor);}}
    var data=node as DataGrid;if(data!=null)data.RowHeight=35*factor;
   }foreach(var change in changes)change();GlassChrome.AlignHeader(window,factor);if(window is MainWindow||window is ChallengeWindow){double delta=Math.Max(0,AppSettings.InterfaceFont-13);window.MinWidth=Math.Min(SystemParameters.WorkArea.Width,state.MinWidth+delta*45);window.MinHeight=Math.Min(SystemParameters.WorkArea.Height,state.MinHeight+delta*35);}else FitDialog(window,state,factor);state.Applied=AppSettings.InterfaceFont;CompactChallenge(window);
  }finally{state.Busy=false;}}
 static void FitDialog(Window w,WindowState state,double factor){double availableWidth=SystemParameters.WorkArea.Width-32,availableHeight=SystemParameters.WorkArea.Height-40;if(w.Owner!=null&&w.Owner.IsVisible){availableWidth=Math.Min(availableWidth,Math.Max(620,w.Owner.ActualWidth-32));availableHeight=Math.Min(availableHeight,Math.Max(400,w.Owner.ActualHeight-40));}w.MinWidth=Math.Min(state.MinWidth,availableWidth);w.MinHeight=Math.Min(state.MinHeight,availableHeight);w.MaxWidth=Math.Max(w.MinWidth,Math.Min(state.MaxWidth,availableWidth));w.MaxHeight=Math.Max(w.MinHeight,Math.Min(state.MaxHeight,availableHeight));if(!double.IsNaN(state.Width))w.Width=Math.Min(w.MaxWidth,Math.Max(w.MinWidth,state.Width*factor));if(!double.IsNaN(state.Height)&&w.SizeToContent==SizeToContent.Manual)w.Height=Math.Min(w.MaxHeight,Math.Max(w.MinHeight,state.Height*factor));}
 static void CompactChallenge(Window w){var game=w as ChallengeWindow;if(game==null||game.Content==null)return;var root=game.Content as Grid;if(root==null)return;var all=Walk(root,new HashSet<DependencyObject>()).OfType<Grid>().ToList();bool compact=root.ActualHeight>0&&root.ActualHeight<850;foreach(var grid in all){foreach(var row in grid.RowDefinitions){LengthState value;if(!lengths.TryGetValue(row,out value))continue;double height=value.Length*Factor;if(compact){if(Math.Abs(value.Length-92)<.1)height=Math.Min(height,100);else if(Math.Abs(value.Length-158)<.1)height=158;else if(Math.Abs(value.Length-58)<.1)height=Math.Min(height,65);else if(Math.Abs(value.Length-148)<.1)height=Math.Min(height,116);else if(Math.Abs(value.Length-76)<.1)height=Math.Min(height,76);}if(Math.Abs(row.Height.Value-height)>.05)row.Height=new GridLength(height);}}}
}
